// Minimal HTMX-like implementation for demonstration
(function() {
    document.addEventListener('DOMContentLoaded', function() {
        // Handle hx-get attributes
        document.querySelectorAll('[hx-get]').forEach(function(el) {
            el.addEventListener('click', function(e) {
                e.preventDefault();
                var url = el.getAttribute('hx-get');
                var target = document.querySelector(el.getAttribute('hx-target'));
                var swap = el.getAttribute('hx-swap') || 'innerHTML';
                
                fetch(url)
                    .then(function(response) { return response.text(); })
                    .then(function(html) {
                        if (target && swap === 'innerHTML') {
                            target.innerHTML = html;
                        }
                    })
                    .catch(function(error) {
                        console.error('Error:', error);
                    });
            });
        });
    });
})();
